mapper.select:
SELECT COUNT(*)
FROM file_system
WHERE file_system_group_id = #{groupId}

WITH RECURSIVE group_tree AS ( -- 查询指定分组 SELECT file_system_group_id FROM file_system_group WHERE file_system_group_id = #{groupId}
UNION ALL
-- 递归查询子分组 SELECT g.file_system_group_id FROM file_system_group g INNER JOIN group_tree gt ON g.file_system_group_parent_id = gt.file_system_group_id ) SELECT file_system_group_id FROM group_tree
